INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100610, "物理防御力（ダウン不可）アップ", "boss_def_lower_limit", 10061003, "バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100610, "魔法防御力（ダウン不可）アップ", "boss_magic_def_lower_limit", 10061004, "バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100610, "ＴＰダウンカット", "boss_tp_down_cut", 10061005, "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100610, "ＴＰ上昇ダウン", 3, 10061006, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100610, "ＨＰ吸収ダウン", 9, 10061007, "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。");
